  add('entree','Petite salade de quinoa',20,'casserole','quinoa:120;concombre:1;tomate:2;citron:1','Rincer puis cuire le quinoa suivant le paquet. / Laisser tiédir, ajouter concombre et tomates. / Assaisonner au citron.','🥗');
  add('entree','Champignons à la crème',15,'poêle','champignon:300;creme:80;ail:8;huile:10','Nettoyer et émincer les champignons. / Les faire revenir avec l’ail dans l’huile pendant 8 minutes. / Ajouter la crème et chauffer 2 minutes.','🍄');
  add('entree','Salade pomme et noix',10,'froid','salade:120;pomme:1;noix:50;chevre:70','Laver la salade, couper la pomme. / Répartir le fromage et les noix, mélanger.','🥗');
  add('entree','Petits pois à la crème',15,'casserole','petits_pois:300;beurre:15;creme:40','Cuire les petits pois dans l’eau bouillante environ 8 minutes puis égoutter. / Ajouter le beurre et la crème, servir tiède.','🫛');
  // Plats (66)
  add('plat','Omelette jambon-fromage',12,'poêle','oeuf:4;jambon:2;fromage:65;beurre:12','Battre les œufs. / Faire revenir le jambon coupé en dés dans le beurre. / Verser les œufs, ajouter le fromage et plier quand l’omelette est prise.','🍳');
  add('plat','Omelette aux pommes de terre',25,'poêle','oeuf:4;pomme_terre:350;oignon:1;huile:20','Couper les pommes de terre en petits dés. / Les cuire avec l’oignon dans une poêle couverte jusqu’à tendreté. / Verser les œufs battus et laisser prendre des deux côtés.','🍳');
  add('plat','Omelette aux champignons',18,'poêle','oeuf:4;champignon:250;beurre:15;fromage:40','Faire revenir les champignons émincés dans le beurre. / Ajouter les œufs battus et le fromage. / Cuire doucement puis replier.','🍳');
  add('plat','Pâtes jambon-crème',20,'casserole','pates:180;jambon:2;creme:140;fromage:45','Cuire les pâtes selon l’emballage. / Réchauffer le jambon émincé dans la crème. / Égoutter les pâtes et les mélanger à la sauce et au fromage.','🍝');
  add('plat','Spaghetti bolognaise',35,'casserole','pates:180;boeuf:250;coulis:250;oignon:1;huile:15','Cuire les pâtes. / Faire revenir l’oignon et le bœuf dans l’huile. / Ajouter le coulis et laisser mijoter 15 minutes avant de servir sur les pâtes.','🍝');
  add('plat','Spaghetti tomate-basilic',20,'casserole','pates:180;coulis:240;ail:8;herbes:6;huile:15','Cuire les pâtes. / Chauffer le coulis avec ail et herbes dans l’huile 10 minutes. / Mélanger aux pâtes égouttées.','🍝');
  add('plat','Pâtes carbonara façon familiale',20,'casserole','pates:180;lardons:120;oeuf:2;parmesan:50','Cuire les pâtes. / Faire dorer les lardons. / Fouetter les œufs avec le parmesan ; hors du feu, mélanger aux pâtes chaudes puis incorporer les lardons.','🍝','Utiliser des œufs très frais ; servir immédiatement.');
  add('plat','Pâtes au thon et tomate',22,'casserole','pates:180;thon:140;coulis:240;oignon:1','Cuire les pâtes. / Faire mijoter l’oignon et le coulis 10 minutes. / Ajouter le thon égoutté, puis mélanger aux pâtes.','🍝');
  add('plat','Pâtes aux courgettes',25,'poêle','pates:180;courgette:300;creme:120;parmesan:35;huile:15','Cuire les pâtes. / Faire revenir les courgettes en demi-rondelles dans l’huile 10 minutes. / Ajouter crème, parmesan puis pâtes égouttées.','🍝');
  add('plat','Gratin de pâtes',35,'four','pates:200;creme:180;fromage:100;jambon:2','Préchauffer le four à 200 °C et cuire les pâtes al dente. / Mélanger les pâtes avec le jambon coupé, la crème et la moitié du fromage. / Répartir dans un plat, couvrir du reste du fromage et gratiner 15 minutes.','🧀');
  add('plat','Macaroni au fromage',25,'casserole','pates:200;lait:220;fromage:130;beurre:20;farine:20','Cuire les pâtes. / Fondre le beurre, ajouter la farine puis le lait petit à petit jusqu’à épaississement. / Faire fondre le fromage dans cette sauce et mélanger aux pâtes.','🧀');
  add('plat','Riz sauté aux légumes',20,'poêle','riz_cuit:350;carotte:160;petits_pois:120;oeuf:2;sauce_soja:25;huile:15','Faire revenir les carottes en petits dés dans l’huile jusqu’à tendreté. / Ajouter les petits pois puis le riz déjà cuit et bien chaud. / Brouiller les œufs dans un coin de la poêle, mélanger avec la sauce soja.','🍚','Utiliser du riz conservé rapidement au froid et bien réchauffé.');
  add('plat','Riz au poulet et carottes',30,'casserole','riz:160;poulet:260;carotte:200;oignon:1;huile:15','Cuire le riz selon le paquet. / Faire revenir le poulet coupé en petits morceaux avec l’oignon et les carottes. / Cuire complètement le poulet puis mélanger au riz.','🍚');
  add('plat','Risotto aux champignons',35,'casserole','riz:180;champignon:250;bouillon:1;oignon:1;beurre:20;parmesan:40','Faire revenir l’oignon et les champignons. / Ajouter le riz et verser progressivement environ 600 ml de bouillon chaud jusqu’à cuisson, en remuant. / Incorporer beurre et parmesan.','🍄','Préférer un riz à risotto si disponible.');
  add('plat','Riz à la tomate',25,'casserole','riz:180;coulis:220;oignon:1;huile:15','Faire revenir l’oignon dans l’huile. / Ajouter le riz, le coulis et de l’eau selon le riz utilisé. / Cuire à couvert jusqu’à absorption, en vérifiant la cuisson.','🍚');
  add('plat','Curry de poulet',35,'casserole','poulet:280;riz:160;creme:160;curry:8;oignon:1;huile:15','Cuire le riz. / Faire dorer le poulet avec l’oignon dans l’huile. / Ajouter curry et crème, laisser mijoter jusqu’à cuisson complète du poulet. / Servir avec le riz.','🍛');
  add('plat','Curry de pois chiches',25,'casserole','pois_chiches:300;coulis:220;creme:120;curry:8;riz:150','Cuire le riz. / Faire mijoter pois chiches rincés, coulis, crème et curry 15 minutes. / Servir sur le riz.','🍛');
  add('plat','Poulet rôti et pommes de terre',55,'four','poulet:350;pomme_terre:500;huile:25;herbes:5','Préchauffer le four à 200 °C. / Disposer le poulet et les pommes de terre coupées dans un plat, arroser d’huile et ajouter les herbes. / Cuire environ 40 à 45 minutes, jusqu’à cuisson complète du poulet.','🍗');
  add('plat','Poulet à la crème et champignons',35,'poêle','poulet:300;champignon:250;creme:180;oignon:1;huile:15','Faire revenir le poulet avec l’oignon et l’huile. / Ajouter les champignons, puis la crème. / Laisser mijoter jusqu’à cuisson complète du poulet et servir.','🍗');
  add('plat','Escalopes de poulet citron',25,'poêle','poulet:300;citron:1;beurre:20;riz:150','Cuire le riz. / Dorer les escalopes dans le beurre, vérifier leur cuisson complète. / Ajouter le jus de citron et servir avec le riz.','🍋');
  add('plat','Poulet aux courgettes',30,'poêle','poulet:280;courgette:360;creme:100;huile:15','Faire revenir le poulet émincé dans l’huile. / Ajouter les courgettes en dés et faire cuire à couvert. / Terminer par la crème et vérifier la cuisson complète du poulet.','🍗');
  add('plat','Quiche lorraine',45,'four','pate_brisee:1;lardons:160;oeuf:3;creme:200;lait:80','Préchauffer le four à 190 °C. / Faire dorer les lardons et les répartir sur la pâte dans un moule. / Fouetter œufs, crème et lait, verser puis cuire environ 30 minutes.','🥧');
  add('plat','Quiche jambon-fromage',45,'four','pate_brisee:1;jambon:3;oeuf:3;creme:180;fromage:100','Préchauffer le four à 190 °C. / Garnir la pâte de jambon et de fromage. / Verser le mélange œufs-crème et cuire 30 minutes environ.','🥧');
  add('plat','Quiche aux courgettes',45,'four','pate_brisee:1;courgette:300;oeuf:3;creme:160;fromage:80','Préchauffer le four à 190 °C. / Faire revenir les courgettes quelques minutes puis les répartir sur la pâte. / Verser œufs battus, crème et fromage puis cuire environ 30 minutes.','🥧');
  add('plat','Tarte tomate-moutarde',40,'four','pate_feuilletee:1;tomate:4;moutarde:25;fromage:90','Préchauffer le four à 200 °C. / Étaler la moutarde sur la pâte. / Disposer les tomates tranchées, parsemer de fromage et cuire environ 25 minutes.','🥧');
  add('plat','Pizza maison rapide',35,'four','pate_feuilletee:1;coulis:160;mozzarella:150;jambon:2;champignon:100','Préchauffer le four à 200 °C. / Étaler le coulis sur la pâte et ajouter les garnitures. / Cuire environ 20 à 25 minutes, jusqu’à pâte dorée.','🍕','Version rapide sur pâte feuilletée ; texture différente d’une pâte à pizza.');
  add('plat','Croque-monsieur',15,'poêle','pain:8;jambon:4;fromage:100;beurre:20','Garnir quatre sandwiches de jambon et de fromage. / Beurrer légèrement les faces extérieures. / Dorer 3 à 4 minutes de chaque côté dans une poêle, jusqu’à fromage fondu.','🥪');
  add('plat','Croque-madame',20,'poêle','pain:8;jambon:4;fromage:100;oeuf:2;beurre:20','Préparer et dorer quatre croques au jambon-fromage. / Cuire les œufs au plat séparément. / Servir avec un œuf sur une portion de croque par personne.','🍳');
  add('plat','Sandwich poulet-crudités',15,'froid','pain:4;poulet_cuit:200;salade:80;tomate:2;mayonnaise:35','Couper le poulet déjà cuit en fines lamelles. / Garnir le pain de salade, tomate, mayonnaise et poulet. / Servir bien frais.','🥪');
  add('plat','Wraps au thon',12,'froid','pain_wrap:4;thon:160;salade:90;tomate:2;mayonnaise:35','Mélanger le thon égoutté et la mayonnaise. / Garnir les tortillas avec la salade, la tomate et le thon. / Rouler et couper.','🌯');
  add('plat','Wraps au poulet',15,'froid','pain_wrap:4;poulet_cuit:220;salade:90;tomate:2;yaourt:1','Mélanger le yaourt avec des herbes selon le goût. / Garnir les tortillas de poulet déjà cuit, salade et tomate, puis rouler.','🌯');
