  add('plat','Lentilles aux carottes',35,'casserole','lentilles:180;carotte:220;oignon:1;bouillon:1','Rincer les lentilles. / Couper les légumes et cuire le tout dans de l’eau avec le bouillon pendant 25 à 30 minutes. / Égoutter si nécessaire.','🥕');
  add('plat','Poisson au citron et riz',30,'poêle','poisson:300;riz:160;citron:1;beurre:20','Cuire le riz selon le paquet. / Cuire le poisson à cœur dans le beurre, en le retournant délicatement. / Arroser de citron et servir avec le riz.','🐟');
  add('plat','Poisson au four et carottes',40,'four','poisson:320;carotte:350;huile:20;citron:1','Préchauffer le four à 190 °C. / Précuire les carottes 10 minutes dans l’eau. / Les placer avec le poisson dans un plat, arroser d’huile et citron puis cuire 15 à 20 minutes selon l’épaisseur.','🐟');
  add('plat','Saumon au four',30,'four','saumon:320;citron:1;riz:160;huile:10','Préchauffer le four à 190 °C. / Cuire le riz. / Déposer le saumon dans un plat avec citron et huile, enfourner 15 à 20 minutes jusqu’à cuisson à cœur.','🐟');
  add('plat','Saumon à la crème et pâtes',25,'poêle','saumon:260;pates:180;creme:150;citron:1','Cuire les pâtes. / Poêler le saumon jusqu’à cuisson complète et le détailler. / Ajouter la crème et un filet de citron, mélanger avec les pâtes.','🍝');
  add('plat','Crevettes à l’ail et riz',25,'poêle','crevettes:280;ail:10;riz:160;huile:20;citron:1','Cuire le riz. / Saisir les crevettes décortiquées et l’ail dans l’huile jusqu’à cuisson complète. / Arroser de citron et servir sur le riz.','🍤');
  add('plat','Poêlée courgettes et riz',25,'poêle','courgette:400;riz:170;oignon:1;huile:20;fromage:50','Cuire le riz. / Faire revenir oignon et courgettes dans l’huile jusqu’à tendreté. / Mélanger au riz et saupoudrer de fromage.','🍚');
  add('plat','Gratin de courgettes',45,'four','courgette:550;oeuf:2;creme:160;fromage:100','Préchauffer le four à 190 °C. / Faire dégorger les courgettes légèrement précuites. / Verser dans un plat, ajouter le mélange œufs-crème, parsemer de fromage et cuire 25 minutes.','🥒');
  add('plat','Poêlée de légumes au quinoa',30,'poêle','quinoa:170;courgette:250;carotte:200;poivron:1;huile:20','Cuire le quinoa selon le paquet. / Faire revenir les légumes en petits dés dans l’huile jusqu’à tendreté. / Mélanger et servir.','🥗');
  add('plat','Tortilla pommes de terre',30,'poêle','pomme_terre:450;oeuf:5;oignon:1;huile:25','Faire cuire les pommes de terre tranchées et l’oignon dans l’huile jusqu’à tendreté. / Mélanger aux œufs battus. / Cuire doucement en retournant la tortilla à l’aide d’une assiette.','🍳');
  add('plat','Galettes de pommes de terre',30,'poêle','pomme_terre:500;oeuf:1;farine:40;oignon:1;huile:25','Râper pommes de terre et oignon, presser pour retirer l’excédent d’eau. / Ajouter œuf et farine. / Cuire de petites galettes 4 à 5 minutes de chaque côté dans l’huile.','🥔');
  add('plat','Soupe-repas aux légumes',40,'casserole','pomme_terre:350;carotte:300;poireau:2;bouillon:1;pain:2','Éplucher et détailler les légumes. / Cuire 30 minutes dans une casserole d’eau avec le bouillon. / Mixer partiellement et servir avec le pain.','🥣');
  add('plat','Soupe-repas aux lentilles',40,'casserole','lentilles:190;carotte:200;oignon:1;coulis:150;bouillon:1','Faire revenir brièvement l’oignon. / Ajouter carottes, lentilles, coulis, eau et bouillon. / Cuire jusqu’à lentilles tendres, environ 30 minutes.','🥣');
  add('plat','Œufs cocotte à la crème',20,'four','oeuf:4;creme:100;fromage:50;pain:4','Préchauffer le four à 180 °C. / Verser la crème dans deux ramequins, casser les œufs et parsemer de fromage. / Cuire au bain-marie 10 à 12 minutes, selon la prise souhaitée, et servir avec pain.','🥚');
  add('plat','Œufs à la tomate',25,'poêle','oeuf:4;coulis:280;oignon:1;poivron:1;huile:15','Faire revenir oignon et poivron dans l’huile. / Ajouter le coulis et cuire 10 minutes. / Creuser quatre trous, casser les œufs et cuire à couvert jusqu’à ce que les blancs soient pris.','🍳');
  add('plat','Saucisses et lentilles',45,'casserole','saucisse:2;lentilles:200;carotte:170;oignon:1;bouillon:1','Faire cuire lentilles, carottes et oignon dans de l’eau avec le bouillon pendant 25 à 30 minutes. / Cuire les saucisses complètement selon leur type et les ajouter aux lentilles.','🍲');
  add('plat','Porc à la moutarde',35,'poêle','porc:300;moutarde:30;creme:140;riz:150','Cuire le riz. / Saisir le porc à la poêle et poursuivre la cuisson à cœur. / Ajouter crème et moutarde, laisser épaissir quelques minutes et servir.','🍲');
  add('plat','Rôti de porc aux pommes de terre',65,'four','porc:350;pomme_terre:500;oignon:1;huile:20','Préchauffer le four à 190 °C. / Déposer le porc avec pommes de terre, oignon et huile dans un plat. / Rôtir environ 50 minutes selon l’épaisseur, en vérifiant la cuisson à cœur.','🍖');
  add('plat','Poêlée de restes de pâtes',15,'poêle','pates_cuites:400;oeuf:2;fromage:70;huile:15','Réchauffer complètement les pâtes déjà cuites dans l’huile. / Ajouter les œufs battus, remuer jusqu’à cuisson. / Parsemer de fromage.','🍝','Utiliser des restes rapidement refroidis puis conservés au réfrigérateur.');
  add('plat','Riz sauté au poulet restant',18,'poêle','riz_cuit:350;poulet_cuit:200;petits_pois:120;sauce_soja:25;huile:15','Faire revenir les petits pois dans l’huile. / Ajouter le riz et le poulet déjà cuits ; réchauffer complètement. / Ajouter la sauce soja et servir aussitôt.','🍚','Restes refroidis rapidement, conservés au froid et réchauffés correctement.');
  add('plat','Croquettes de riz au fromage',25,'poêle','riz_cuit:360;oeuf:2;fromage:90;chapelure:60;huile:25','Mélanger le riz froid, les œufs et le fromage. / Former des galettes et les passer dans la chapelure. / Dorer de chaque côté dans l’huile jusqu’à cœur bien chaud.','🍚');
  add('plat','Riz crémeux aux champignons',20,'poêle','riz_cuit:360;champignon:220;creme:120;fromage:50','Cuire les champignons émincés à la poêle. / Ajouter le riz déjà cuit, réchauffer complètement et incorporer la crème. / Terminer avec le fromage.','🍄');
  add('plat','Pommes de terre farcies au jambon',55,'four','pomme_terre:600;jambon:2;creme:100;fromage:90','Préchauffer le four à 200 °C. / Cuire les pommes de terre entières environ 40 minutes jusqu’à tendreté. / Les ouvrir, garnir de jambon, crème et fromage, puis gratiner 8 minutes.','🥔');
  // Desserts (26)
  add('dessert','Salade de fruits',10,'froid','pomme:1;banane:1;orange:2;kiwi:2','Éplucher et couper les fruits en morceaux réguliers. / Mélanger dans un saladier et servir frais.','🍓');
  add('dessert','Pommes au four',35,'four','pomme:2;beurre:20;miel:30;cannelle:2','Préchauffer le four à 180 °C. / Évider les pommes, garnir de beurre, miel et cannelle. / Cuire environ 25 minutes jusqu’à tendreté.','🍎');
  add('dessert','Compote de pommes maison',25,'casserole','pomme:4;sucre:25;cannelle:2','Peler et couper les pommes. / Faire compoter à couvert avec un peu d’eau 15 à 20 minutes. / Ajouter le sucre et la cannelle, écraser selon la texture souhaitée.','🍏');
  add('dessert','Bananes poêlées au miel',10,'poêle','banane:2;beurre:15;miel:30','Couper les bananes dans la longueur. / Les dorer doucement dans le beurre, puis ajouter le miel en fin de cuisson.','🍌');
  add('dessert','Yaourt miel et noix',5,'froid','yaourt:2;miel:30;noix:40','Verser les yaourts dans deux bols. / Ajouter le miel et les noix concassées.','🍯');
  add('dessert','Mousse au chocolat',20,'froid','chocolat:120;oeuf:3','Faire fondre le chocolat puis le laisser tiédir. / Séparer les œufs, incorporer les jaunes au chocolat. / Monter les blancs en neige et les incorporer délicatement. / Réserver au froid au moins 3 heures.','🍫','Contient des œufs crus : déconseillé aux personnes à risque ; utiliser une recette avec œufs pasteurisés au besoin.');
  add('dessert','Crème chocolat',20,'casserole','lait:400;chocolat:100;sucre:30;farine:25','Chauffer doucement le lait et le chocolat. / Délayer farine et sucre dans un peu de lait froid, ajouter en fouettant. / Cuire à feu doux jusqu’à épaississement puis laisser refroidir.','🍫');
  add('dessert','Riz au lait',45,'casserole','riz:110;lait:500;sucre:50;vanille:2','Verser riz, lait et vanille dans une casserole. / Cuire à feu doux 35 à 40 minutes en remuant souvent. / Ajouter le sucre en fin de cuisson et laisser tiédir.','🍚');
  add('dessert','Semoule au lait',15,'casserole','semoule:75;lait:450;sucre:45;vanille:2','Chauffer le lait avec la vanille. / Verser la semoule en pluie et remuer 5 à 7 minutes selon le produit. / Sucrer puis répartir dans deux bols.','🥣');
  add('dessert','Crêpes au sucre',25,'poêle','farine:130;lait:260;oeuf:2;beurre:15;sucre:40','Préparer une pâte lisse avec farine, œufs, lait et beurre fondu. / Cuire les crêpes à la poêle. / Saupoudrer de sucre au moment de servir.','🥞');
  add('dessert','Crêpes chocolat',25,'poêle','farine:130;lait:260;oeuf:2;beurre:15;chocolat:80','Préparer la pâte et cuire les crêpes. / Faire fondre le chocolat au bain-marie. / Napper les crêpes de chocolat fondu.','🥞');
  add('dessert','Pain perdu sucré',15,'poêle','pain:4;oeuf:2;lait:130;sucre:40;beurre:20','Fouetter œufs, lait et sucre. / Tremper le pain puis cuire à la poêle dans le beurre jusqu’à dorure des deux côtés.','🍞');
  add('dessert','Mug cake chocolat',10,'micro-ondes','farine:50;sucre:35;cacao:20;lait:65;huile:20;levure:3','Mélanger les ingrédients dans deux grandes tasses adaptées au micro-ondes. / Cuire par intervalles de 30 secondes, environ 1 à 2 minutes selon la puissance. / Laisser tiédir et vérifier la cuisson.','🍫');
  add('dessert','Gâteau au yaourt miniature',40,'four','yaourt:1;farine:120;sucre:90;oeuf:2;huile:45;levure:6','Préchauffer le four à 180 °C. / Mélanger yaourt, œufs, sucre puis farine, levure et huile. / Verser dans un petit moule et cuire environ 25 à 30 minutes, jusqu’à lame sèche.','🍰');
  add('dessert','Fondant chocolat individuel',25,'four','chocolat:100;beurre:70;oeuf:2;sucre:60;farine:35','Préchauffer le four à 180 °C. / Fondre chocolat et beurre, ajouter œufs, sucre et farine. / Verser dans deux ramequins et cuire environ 12 à 15 minutes selon la texture souhaitée.','🍫');
  add('dessert','Cookies chocolat',25,'four','farine:130;beurre:65;sucre:70;oeuf:1;chocolat:80;levure:3','Préchauffer le four à 180 °C. / Mélanger beurre mou et sucre, puis œuf, farine, levure et chocolat haché. / Former de petits tas et cuire 10 à 12 minutes.','🍪');
  add('dessert','Crumble aux pommes',40,'four','pomme:3;farine:100;beurre:65;sucre:70;cannelle:2','Préchauffer le four à 180 °C. / Mettre les pommes coupées dans un petit plat. / Sabler farine, beurre et sucre du bout des doigts, répartir sur les fruits et cuire 25 minutes.','🍎');
  add('dessert','Tarte fine aux pommes',35,'four','pate_feuilletee:1;pomme:3;sucre:35;beurre:20','Préchauffer le four à 200 °C. / Étaler la pâte, disposer de fines tranches de pomme. / Parsemer de sucre et de noisettes de beurre puis cuire 20 à 25 minutes.','🥧');
  add('dessert','Poires au chocolat',15,'casserole','poire:2;chocolat:90;lait:40','Peler et couper les poires. / Faire fondre doucement le chocolat avec le lait. / Napper les poires et servir.','🍐');
  add('dessert','Verrine fromage blanc-framboises',5,'froid','fromage_blanc:300;framboise:160;miel:30','Répartir le fromage blanc dans deux verrines. / Ajouter les framboises puis le miel.','🍓');
  add('dessert','Verrine banane-biscuit',8,'froid','banane:2;yaourt:2;biscuit:60;chocolat:30','Écraser grossièrement les biscuits et couper les bananes. / Alterner yaourt, banane et biscuits. / Parsemer de chocolat râpé.','🍌');
  add('dessert','Salade orange-cannelle',8,'froid','orange:3;miel:20;cannelle:2','Peler les oranges à vif et couper en rondelles. / Ajouter le miel et une pincée de cannelle.','🍊');
  add('dessert','Yaourt pomme caramélisée',12,'poêle','pomme:2;yaourt:2;beurre:15;sucre:25','Couper les pommes en dés puis les faire dorer dans le beurre avec le sucre. / Servir tièdes sur les yaourts.','🍏');
  add('dessert','Bananes au chocolat',10,'casserole','banane:2;chocolat:80;noix:30','Couper les bananes dans deux bols. / Faire fondre le chocolat et le verser sur les fruits. / Ajouter les noix concassées.','🍌');
  add('dessert','Fruits rouges façon crumble minute',10,'poêle','fraise:160;framboise:100;biscuit:70;yaourt:2','Rincer les fruits et les couper si nécessaire. / Émietter les biscuits. / Servir les fruits sur les yaourts et parsemer de biscuits.','🍓');
  add('dessert','Pomme et raisins secs tièdes',12,'poêle','pomme:2;raisins_secs:50;beurre:15;cannelle:2','Faire revenir les pommes en dés dans le beurre. / Ajouter les raisins secs et une pincée de cannelle. / Cuire jusqu’à tendreté et servir tiède.','🍎');
